void FFmpegVideoDecodeEngine_Initialize(MessageLoop* message_loop, VideoDecodeEngine::EventHandler* event_handler, VideoDecodeContext* context, const VideoDecoderConfig& config) {
    AVCodecContext* codec_ctx = avcodec_alloc_context3(NULL);
    if (!codec_ctx) {
        // Handle error
        return;
    }

    // Setup codec context parameters based on config
    codec_ctx->thread_count = 4; // default thread count

    // Configure codec specific parameters
    if (config.profile != 0) {
        codec_ctx->profile = config.profile;
    }

    // Setup buffer pool
    AVBufferPool* buffer_pool = av_buffer_pool_init2(codec_ctx->width, codec_ctx->height, &avcodec_get_frame_defaults, NULL, NULL, NULL);
    if (!buffer_pool) {
        avcodec_free_context(&codec_ctx);
        // Handle error
        return;
    }

    // Check available buffers
    AVFrame* frame = av_frame_alloc();
    if (!frame) {
        av_buffer_pool_uninit(&buffer_pool);
        avcodec_free_context(&codec_ctx);
        // Handle error
        return;
    }

    // Initialize the codec
    int ret = avcodec_open2(codec_ctx, avcodec_find_decoder(codec_ctx->codec_id), NULL);
    if (ret < 0) {
        av_frame_free(&frame);
        av_buffer_pool_uninit(&buffer_pool);
        avcodec_free_context(&codec_ctx);
        // Handle error
        return;
    }

    // Notify event handler
    event_handler->onInitializationComplete(message_loop, context, codec_ctx);
}

